/**
 * TT Creators + Biblioteca — Endpoint central v2
 * ─────────────────────────────────────────────────────────────────
 * Gestiona todos los endpoints REST de Tiritaito:
 *   TT Creators:
 *   - Leer / escribir wp_options  (/tiritaito/v1/datos)
 *   - Listar medios               (/tiritaito/v1/medios)
 *   - Subir archivos              (/tiritaito/v1/subir)
 *   - Eliminar un medio           (/tiritaito/v1/medio/{id})
 *   - Listar / crear entradas     (/tiritaito/v1/entradas)
 *   - Editar / eliminar entrada   (/tiritaito/v1/entrada/{id})
 *
 *   Biblioteca:
 *   - Subir portada desde galería (/biblioteca/v1/subir)
 *   - Importar portada desde URL  (/biblioteca/v1/portada-url)
 * ─────────────────────────────────────────────────────────────────
 */

// ════════════════════════════════════════════════════════════════
// 1. TOKENS
// ════════════════════════════════════════════════════════════════
if ( ! defined( 'TT_READ_TOKEN' ) ) {
    define( 'TT_READ_TOKEN', '19274523619548932ndfdjisfhbcndjsa7548930jyrhrewuohyrufnhfeuioahsjnsqoyr349790r49802ymfh9u02ry' );
}
if ( ! defined( 'TT_WRITE_TOKEN' ) ) {
    define( 'TT_WRITE_TOKEN', 'gjtieohty5775899340ynthreuwovhngj920789tmfjri92ioyt5782nyuhei20789207489ynhr648924382689732673489267t839h6ty89djyx78t' );
}
// [NUEVO] Token para la app Biblioteca — ASCII puro obligatorio.
if ( ! defined( 'BIBLIOTECA_TOKEN' ) ) {
    define( 'BIBLIOTECA_TOKEN', 'bib2026Xk9mPqR7nLsTvWjcYeZhA' );
}

// ════════════════════════════════════════════════════════════════
// 2. LÍMITES DE SEGURIDAD
// ════════════════════════════════════════════════════════════════
define( 'TT_RATE_LIMIT', 60 );
define( 'TT_MAX_SIZE', 200 * 1024 * 1024 );
define( 'TT_MIMES_OK', [
    'image/jpeg', 'image/png', 'image/gif', 'image/webp',
    'video/mp4', 'video/quicktime', 'video/x-msvideo', 'video/webm',
    'audio/mpeg', 'audio/mp4', 'audio/wav', 'audio/ogg', 'audio/x-m4a',
    'application/pdf',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/json',
] );

// ════════════════════════════════════════════════════════════════
// 3. WHITELIST DE CLAVES wp_options
// ════════════════════════════════════════════════════════════════
function tt_opciones_permitidas() {
    return [
        'tt_virgen'              => 'textarea',
        'tt_brisa'               => 'textarea',
        'tt_homilia_audio'       => 'url',
        'tt_homilia_texto'       => 'textarea',
        'tt_lenguas_url'         => 'url',
        'tt_tip_1'               => 'url',
        'tt_tip_2'               => 'url',
        'tt_docx_lectura_url'    => 'url',
        'tt_youtube_json_url'    => 'url',
        'tt_seminarios_json_url' => 'url',
        'tt_viacrucis_json_url'  => 'url',
        'tt_fiesta_dias'         => 'textarea',
        'tt_novedades'           => 'textarea', // JSON de novedades — mismo patrón que tt_fiesta_dias
        'tt_promesa'             => 'url',      // imagen de la Promesa de Dios (subida desde la app)
        'tt_papa_leon'           => 'textarea', // JSON: {imagen_url, media_id, fecha_lugar, frase, texto, enlace, etiqueta}
    ];
}

// ════════════════════════════════════════════════════════════════
// 4. CORS
// [MODIFICADO] Se añade X-Biblioteca-Token a los Allow-Headers
// y un hook init prioridad 0 para interceptar OPTIONS antes de
// que WordPress pueda devolver 404 para namespaces no cargados.
// ════════════════════════════════════════════════════════════════

// Preflight temprano — cubre ambas apps antes de que WP procese nada.
add_action( 'init', function () {
    if ( ! isset( $_SERVER['REQUEST_METHOD'] ) ) return;
    if ( $_SERVER['REQUEST_METHOD'] !== 'OPTIONS' ) return;

    header( 'Access-Control-Allow-Origin: *' );
    header( 'Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS' );
    header( 'Access-Control-Allow-Headers: Content-Type, X-TT-Token, X-Biblioteca-Token' );
    header( 'Access-Control-Max-Age: 86400' );
    status_header( 200 );
    exit;
}, 0 );

add_action( 'rest_api_init', function () {
    remove_filter( 'rest_pre_serve_request', 'rest_send_cors_headers' );
    add_filter( 'rest_pre_serve_request', function ( $value ) {
        header( 'Access-Control-Allow-Origin: *' );
        header( 'Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS' );
        header( 'Access-Control-Allow-Headers: Content-Type, X-TT-Token, X-Biblioteca-Token' );
        return $value;
    } );
}, 15 );

// ════════════════════════════════════════════════════════════════
// 5. AYUDANTES INTERNOS — TT Creators
// ════════════════════════════════════════════════════════════════
function tt_check_write( WP_REST_Request $req ) {
    $token = $req->get_header( 'x-tt-token' );
    if ( empty( $token ) || $token !== TT_WRITE_TOKEN ) {
        return new WP_Error( 'tt_token', 'Token no válido.', [ 'status' => 403 ] );
    }
    $ip  = $_SERVER['REMOTE_ADDR'] ?? 'x';
    $key = 'tt_rl_' . md5( $ip );
    $cnt = (int) get_transient( $key );
    if ( $cnt >= TT_RATE_LIMIT ) {
        return new WP_Error( 'tt_limit', 'Demasiadas peticiones. Espera un momento.', [ 'status' => 429 ] );
    }
    set_transient( $key, $cnt + 1, HOUR_IN_SECONDS );
    return true;
}

function tt_check_read( WP_REST_Request $req ) {
    $token = $req->get_header( 'x-tt-token' );
    if ( empty( $token ) ) {
        $token = $req->get_param( 'token' );
    }
    return ( $token === TT_READ_TOKEN || $token === TT_WRITE_TOKEN );
}

// ════════════════════════════════════════════════════════════════
// 6. AYUDANTES INTERNOS — Biblioteca [NUEVO]
// ════════════════════════════════════════════════════════════════

// Valida el token de Biblioteca con rate limit propio (30/hora por IP).
function bib_check_token( WP_REST_Request $req ) {
    $token = $req->get_header( 'x-biblioteca-token' );
    if ( empty( $token ) || $token !== BIBLIOTECA_TOKEN ) {
        return new WP_Error( 'bib_token', 'Token no válido.', [ 'status' => 403 ] );
    }
    $ip  = $_SERVER['REMOTE_ADDR'] ?? 'x';
    $key = 'bib_rl_' . md5( $ip );
    $cnt = (int) get_transient( $key );
    if ( $cnt >= 30 ) {
        return new WP_Error( 'bib_limit', 'Demasiadas peticiones. Inténtalo más tarde.', [ 'status' => 429 ] );
    }
    set_transient( $key, $cnt + 1, HOUR_IN_SECONDS );
    return true;
}

// Dominios desde los que se permite importar portadas por URL.
function bib_dominios_permitidos() {
    return [
        'covers.openlibrary.org',
        'openlibrary.org',
        'ia.archive.org',
        'archive.org',
        'upload.wikimedia.org',
        'commons.wikimedia.org',
        'books.google.com',
        'books.google.es',
        'm.media-amazon.com',
        'images-amazon.com',
        'ecx.images-amazon.com',
    ];
}

// ════════════════════════════════════════════════════════════════
// 7. REGISTRO DE RUTAS — TT Creators
// ════════════════════════════════════════════════════════════════
add_action( 'rest_api_init', function () {

    register_rest_route( 'tiritaito/v1', '/datos', [
        [ 'methods' => 'GET',  'callback' => 'tt_cb_get_datos',  'permission_callback' => '__return_true' ],
        [ 'methods' => 'POST', 'callback' => 'tt_cb_post_datos', 'permission_callback' => '__return_true' ],
    ] );
    register_rest_route( 'tiritaito/v1', '/medios', [
        [ 'methods' => 'GET', 'callback' => 'tt_cb_get_medios', 'permission_callback' => '__return_true' ],
    ] );
    register_rest_route( 'tiritaito/v1', '/subir', [
        [ 'methods' => 'POST', 'callback' => 'tt_cb_subir', 'permission_callback' => '__return_true' ],
    ] );
    register_rest_route( 'tiritaito/v1', '/medio/(?P<id>\d+)', [
        [ 'methods' => 'DELETE', 'callback' => 'tt_cb_del_medio', 'permission_callback' => '__return_true' ],
    ] );
    register_rest_route( 'tiritaito/v1', '/entradas', [
        [ 'methods' => 'GET',  'callback' => 'tt_cb_get_entradas',  'permission_callback' => '__return_true' ],
        [ 'methods' => 'POST', 'callback' => 'tt_cb_crear_entrada', 'permission_callback' => '__return_true' ],
    ] );
    register_rest_route( 'tiritaito/v1', '/entrada/(?P<id>\d+)', [
        [ 'methods' => 'PUT',    'callback' => 'tt_cb_editar_entrada', 'permission_callback' => '__return_true' ],
        [ 'methods' => 'DELETE', 'callback' => 'tt_cb_del_entrada',    'permission_callback' => '__return_true' ],
    ] );

} );

// ════════════════════════════════════════════════════════════════
// 8. REGISTRO DE RUTAS — Biblioteca [NUEVO]
// ════════════════════════════════════════════════════════════════
add_action( 'rest_api_init', function () {

    register_rest_route( 'biblioteca/v1', '/subir', [
        [ 'methods' => 'POST', 'callback' => 'bib_cb_subir', 'permission_callback' => '__return_true' ],
    ] );
    register_rest_route( 'biblioteca/v1', '/portada-url', [
        [ 'methods' => 'POST', 'callback' => 'bib_cb_portada_url', 'permission_callback' => '__return_true' ],
    ] );

} );

// ════════════════════════════════════════════════════════════════
// 9. CALLBACKS — TT Creators (sin cambios)
// ════════════════════════════════════════════════════════════════

function tt_cb_get_datos( WP_REST_Request $req ) {
    if ( ! tt_check_read( $req ) ) {
        return new WP_Error( 'tt_token', 'Token no válido.', [ 'status' => 403 ] );
    }
    $datos = [];
    foreach ( tt_opciones_permitidas() as $clave => $tipo ) {
        $datos[ $clave ] = get_option( $clave, '' );
    }
    $res = new WP_REST_Response( $datos, 200 );
    $res->header( 'Cache-Control', 'no-store, no-cache, must-revalidate' );
    return $res;
}

function tt_cb_post_datos( WP_REST_Request $req ) {
    $check = tt_check_write( $req );
    if ( is_wp_error( $check ) ) return $check;

    $body = $req->get_json_params();
    if ( empty( $body ) || ! is_array( $body ) ) {
        return new WP_Error( 'tt_vacio', 'Sin datos.', [ 'status' => 400 ] );
    }
    $permitidas = tt_opciones_permitidas();
    $ok = []; $nok = [];
    foreach ( $body as $clave => $valor ) {
        if ( ! array_key_exists( $clave, $permitidas ) ) { $nok[] = $clave; continue; }
        $limpio = $permitidas[ $clave ] === 'url'
            ? esc_url_raw( trim( $valor ) )
            : sanitize_textarea_field( $valor );
        update_option( $clave, $limpio );
        $ok[] = $clave;
    }
    return new WP_REST_Response( [ 'success' => true, 'actualizadas' => $ok, 'rechazadas' => $nok ], 200 );
}

function tt_cb_get_medios( WP_REST_Request $req ) {
    if ( ! tt_check_read( $req ) ) {
        return new WP_Error( 'tt_token', 'Token no válido.', [ 'status' => 403 ] );
    }
    $per   = min( (int) ( $req->get_param( 'per_page' ) ?? 24 ), 100 );
    $page  = max( (int) ( $req->get_param( 'page' )     ?? 1 ),  1 );
    $tipo  = sanitize_text_field( $req->get_param( 'media_type' ) ?? '' );
    $busca = sanitize_text_field( $req->get_param( 'search' )     ?? '' );

    $args = [
        'post_type'      => 'attachment',
        'post_status'    => 'inherit',
        'posts_per_page' => $per,
        'paged'          => $page,
        'orderby'        => 'date',
        'order'          => 'DESC',
    ];
    if ( $tipo && $tipo !== 'all' ) $args['post_mime_type'] = $tipo;
    if ( $busca ) $args['s'] = $busca;

    $q = new WP_Query( $args );
    $items = array_map( function ( $p ) {
        return [
            'id'           => $p->ID,
            'title'        => [ 'rendered' => $p->post_title ],
            'date'         => $p->post_date,
            'source_url'   => wp_get_attachment_url( $p->ID ),
            'media_type'   => strstr( $p->post_mime_type, '/', true ),
            'mime_type'    => $p->post_mime_type,
            'media_details'=> [ 'sizes' => [ 'thumbnail' => [
                'source_url' => wp_get_attachment_image_url( $p->ID, 'thumbnail' ) ?: '',
            ] ] ],
        ];
    }, $q->posts );

    $res = new WP_REST_Response( $items, 200 );
    $res->header( 'X-WP-Total',      $q->found_posts );
    $res->header( 'X-WP-TotalPages', $q->max_num_pages );
    return $res;
}

function tt_cb_subir( WP_REST_Request $req ) {
    $check = tt_check_write( $req );
    if ( is_wp_error( $check ) ) return $check;

    if ( empty( $_FILES['file'] ) || $_FILES['file']['error'] !== UPLOAD_ERR_OK ) {
        $codigo = $_FILES['file']['error'] ?? -1;
        return new WP_Error( 'tt_archivo', "Error en el archivo recibido (código {$codigo}).", [ 'status' => 400 ] );
    }

    $finfo = new finfo( FILEINFO_MIME_TYPE );
    $mime  = $finfo->file( $_FILES['file']['tmp_name'] );
    if ( ! in_array( $mime, TT_MIMES_OK, true ) ) {
        return new WP_Error( 'tt_tipo', "Tipo de archivo no permitido: {$mime}.", [ 'status' => 415 ] );
    }
    if ( $_FILES['file']['size'] > TT_MAX_SIZE ) {
        return new WP_Error( 'tt_size', 'El archivo supera el límite de 200 MB.', [ 'status' => 413 ] );
    }

    require_once ABSPATH . 'wp-admin/includes/file.php';
    require_once ABSPATH . 'wp-admin/includes/media.php';
    require_once ABSPATH . 'wp-admin/includes/image.php';

    $id = media_handle_upload( 'file', 0 );
    if ( is_wp_error( $id ) ) {
        return new WP_Error( 'tt_upload', $id->get_error_message(), [ 'status' => 500 ] );
    }
    return new WP_REST_Response( [
        'id'         => $id,
        'source_url' => wp_get_attachment_url( $id ),
        'title'      => [ 'rendered' => get_the_title( $id ) ],
        'media_type' => strstr( get_post_mime_type( $id ), '/', true ),
    ], 201 );
}

function tt_cb_del_medio( WP_REST_Request $req ) {
    $check = tt_check_write( $req );
    if ( is_wp_error( $check ) ) return $check;

    $id   = (int) $req->get_param( 'id' );
    $post = get_post( $id );
    if ( ! $post || $post->post_type !== 'attachment' ) {
        return new WP_Error( 'tt_404', 'Archivo no encontrado.', [ 'status' => 404 ] );
    }
    if ( ! wp_delete_attachment( $id, true ) ) {
        return new WP_Error( 'tt_del', 'No se pudo eliminar el archivo.', [ 'status' => 500 ] );
    }
    return new WP_REST_Response( [ 'deleted' => true, 'id' => $id ], 200 );
}

function tt_cb_get_entradas( WP_REST_Request $req ) {
    if ( ! tt_check_read( $req ) ) {
        return new WP_Error( 'tt_token', 'Token no válido.', [ 'status' => 403 ] );
    }
    $estado = sanitize_text_field( $req->get_param( 'status' ) ?? 'any' );
    if ( ! in_array( $estado, [ 'publish', 'draft', 'any' ] ) ) $estado = 'any';

    $q = new WP_Query( [
        'post_type'      => 'post',
        'post_status'    => $estado,
        'posts_per_page' => min( (int) ( $req->get_param( 'per_page' ) ?? 20 ), 100 ),
        'paged'          => max( (int) ( $req->get_param( 'page' ) ?? 1 ), 1 ),
        'orderby'        => 'date',
        'order'          => 'DESC',
        's'              => sanitize_text_field( $req->get_param( 'search' ) ?? '' ),
    ] );

    $items = array_map( function ( $p ) {
        $es_avada = strpos( $p->post_content, 'fusion_builder' ) !== false
                 || strpos( $p->post_content, '[fusion_' ) !== false;
        return [
            'id'             => $p->ID,
            'title'          => [ 'rendered' => $p->post_title ],
            'status'         => $p->post_status,
            'date'           => $p->post_date,
            'link'           => get_permalink( $p->ID ),
            'es_avada'       => $es_avada,
            'excerpt'        => wp_trim_words( wp_strip_all_tags( $p->post_content ), 25, '…' ),
            'featured_media' => (int) get_post_thumbnail_id( $p->ID ),
            'featured_url'   => get_the_post_thumbnail_url( $p->ID, 'medium' ) ?: '',
        ];
    }, $q->posts );

    $res = new WP_REST_Response( $items, 200 );
    $res->header( 'X-WP-Total',      $q->found_posts );
    $res->header( 'X-WP-TotalPages', $q->max_num_pages );
    return $res;
}

function tt_cb_crear_entrada( WP_REST_Request $req ) {
    $check = tt_check_write( $req );
    if ( is_wp_error( $check ) ) return $check;

    $body   = $req->get_json_params();
    $titulo = sanitize_text_field( $body['title'] ?? '' );
    if ( empty( $titulo ) ) {
        return new WP_Error( 'tt_titulo', 'El título es obligatorio.', [ 'status' => 400 ] );
    }
    $estado = in_array( $body['status'] ?? 'draft', [ 'publish', 'draft' ] ) ? $body['status'] : 'draft';

    $id = wp_insert_post( [
        'post_title'   => $titulo,
        'post_content' => wp_kses_post( $body['content'] ?? '' ),
        'post_status'  => $estado,
        'post_type'    => 'post',
    ], true );

    if ( is_wp_error( $id ) ) {
        return new WP_Error( 'tt_crear', $id->get_error_message(), [ 'status' => 500 ] );
    }
    if ( ! empty( $body['featured_media'] ) ) {
        set_post_thumbnail( $id, (int) $body['featured_media'] );
    }
    return new WP_REST_Response( [ 'id' => $id, 'link' => get_permalink( $id ) ], 201 );
}

function tt_cb_editar_entrada( WP_REST_Request $req ) {
    $check = tt_check_write( $req );
    if ( is_wp_error( $check ) ) return $check;

    $id   = (int) $req->get_param( 'id' );
    $post = get_post( $id );
    if ( ! $post || $post->post_type !== 'post' ) {
        return new WP_Error( 'tt_404', 'Entrada no encontrada.', [ 'status' => 404 ] );
    }
    if ( strpos( $post->post_content, 'fusion_builder' ) !== false
      || strpos( $post->post_content, '[fusion_' ) !== false ) {
        return new WP_Error( 'tt_avada', 'Esta entrada usa Avada y no puede editarse desde la app.', [ 'status' => 422 ] );
    }

    $body = $req->get_json_params();
    $args = [ 'ID' => $id ];
    if ( isset( $body['title'] ) )   $args['post_title']   = sanitize_text_field( $body['title'] );
    if ( isset( $body['content'] ) ) $args['post_content'] = wp_kses_post( $body['content'] );
    if ( isset( $body['status'] ) && in_array( $body['status'], [ 'publish', 'draft' ] ) ) {
        $args['post_status'] = $body['status'];
    }

    $result = wp_update_post( $args, true );
    if ( is_wp_error( $result ) || ! $result ) {
        $msg = is_wp_error( $result ) ? $result->get_error_message() : 'Error desconocido.';
        return new WP_Error( 'tt_editar', $msg, [ 'status' => 500 ] );
    }
    if ( isset( $body['featured_media'] ) ) {
        $body['featured_media']
            ? set_post_thumbnail( $id, (int) $body['featured_media'] )
            : delete_post_thumbnail( $id );
    }
    return new WP_REST_Response( [ 'id' => $id, 'updated' => true ], 200 );
}

function tt_cb_del_entrada( WP_REST_Request $req ) {
    $check = tt_check_write( $req );
    if ( is_wp_error( $check ) ) return $check;

    $id   = (int) $req->get_param( 'id' );
    $post = get_post( $id );
    if ( ! $post || $post->post_type !== 'post' ) {
        return new WP_Error( 'tt_404', 'Entrada no encontrada.', [ 'status' => 404 ] );
    }
    if ( ! wp_delete_post( $id, true ) ) {
        return new WP_Error( 'tt_del', 'No se pudo eliminar la entrada.', [ 'status' => 500 ] );
    }
    return new WP_REST_Response( [ 'deleted' => true, 'id' => $id ], 200 );
}

// ════════════════════════════════════════════════════════════════
// 10. CALLBACKS — Biblioteca [NUEVO]
// ════════════════════════════════════════════════════════════════

/**
 * Sube una imagen desde el dispositivo a la Biblioteca de Medios de WP.
 * La app envía multipart/form-data con el campo "file".
 */
function bib_cb_subir( WP_REST_Request $req ) {
    $check = bib_check_token( $req );
    if ( is_wp_error( $check ) ) return $check;

    if ( empty( $_FILES['file'] ) || $_FILES['file']['error'] !== UPLOAD_ERR_OK ) {
        $codigo = $_FILES['file']['error'] ?? -1;
        return new WP_Error( 'bib_archivo', "Error en el archivo recibido (código {$codigo}).", [ 'status' => 400 ] );
    }

    // Validar que sea realmente una imagen (por contenido, no por extensión).
    $finfo = new finfo( FILEINFO_MIME_TYPE );
    $mime  = $finfo->file( $_FILES['file']['tmp_name'] );
    $mimes_img = [ 'image/jpeg', 'image/png', 'image/gif', 'image/webp' ];
    if ( ! in_array( $mime, $mimes_img, true ) ) {
        return new WP_Error( 'bib_tipo', 'Solo se permiten imágenes (JPEG, PNG, GIF, WebP).', [ 'status' => 415 ] );
    }
    if ( $_FILES['file']['size'] > 8 * 1024 * 1024 ) {
        return new WP_Error( 'bib_size', 'La imagen pesa más de 8 MB.', [ 'status' => 413 ] );
    }

    require_once ABSPATH . 'wp-admin/includes/file.php';
    require_once ABSPATH . 'wp-admin/includes/media.php';
    require_once ABSPATH . 'wp-admin/includes/image.php';

    $id = media_handle_upload( 'file', 0 );
    if ( is_wp_error( $id ) ) {
        return new WP_Error( 'bib_upload', $id->get_error_message(), [ 'status' => 500 ] );
    }
    return new WP_REST_Response( [
        'url' => wp_get_attachment_url( $id ),
        'id'  => $id,
    ], 201 );
}

/**
 * Descarga una imagen de una URL externa y la guarda en la Biblioteca de Medios.
 * La app envía JSON: { "url": "https://..." }
 */
function bib_cb_portada_url( WP_REST_Request $req ) {
    $check = bib_check_token( $req );
    if ( is_wp_error( $check ) ) return $check;

    $body = $req->get_json_params();
    $url  = esc_url_raw( trim( $body['url'] ?? '' ) );
    if ( empty( $url ) || ! filter_var( $url, FILTER_VALIDATE_URL ) ) {
        return new WP_REST_Response( [ 'error' => 'url_invalida' ], 400 );
    }

    // Verificar que el dominio esté en la lista de permitidos.
    $host = strtolower( parse_url( $url, PHP_URL_HOST ) );
    $permitidos = bib_dominios_permitidos();
    $ok = false;
    foreach ( $permitidos as $d ) {
        if ( $host === $d || str_ends_with( $host, '.' . $d ) ) { $ok = true; break; }
    }
    if ( ! $ok ) {
        return new WP_REST_Response( [ 'error' => 'dominio_no_permitido' ], 403 );
    }

    // Descargar la imagen con wp_remote_get.
    $respuesta = wp_remote_get( $url, [
        'timeout'   => 20,
        'sslverify' => true,
        'headers'   => [ 'User-Agent' => 'Tiritaito-Biblioteca/1.0' ],
    ] );
    if ( is_wp_error( $respuesta ) ) {
        return new WP_REST_Response( [ 'error' => 'descarga_fallida' ], 502 );
    }
    $codigo = wp_remote_retrieve_response_code( $respuesta );
    if ( $codigo !== 200 ) {
        return new WP_REST_Response( [ 'error' => 'descarga_fallida' ], 502 );
    }

    // Validar que sea realmente una imagen.
    $cuerpo = wp_remote_retrieve_body( $respuesta );
    $mime   = '';
    if ( function_exists( 'finfo_open' ) ) {
        $fi   = finfo_open( FILEINFO_MIME_TYPE );
        $mime = finfo_buffer( $fi, $cuerpo );
        finfo_close( $fi );
    }
    $mimes_img = [ 'image/jpeg', 'image/png', 'image/gif', 'image/webp' ];
    if ( ! empty( $mime ) && ! in_array( $mime, $mimes_img, true ) ) {
        return new WP_REST_Response( [ 'error' => 'no_es_imagen' ], 415 );
    }
    if ( strlen( $cuerpo ) > 8 * 1024 * 1024 ) {
        return new WP_REST_Response( [ 'error' => 'demasiado_grande' ], 413 );
    }

    // Guardar en la Biblioteca de Medios usando media_sideload_image.
    require_once ABSPATH . 'wp-admin/includes/file.php';
    require_once ABSPATH . 'wp-admin/includes/media.php';
    require_once ABSPATH . 'wp-admin/includes/image.php';

    $id = media_sideload_image( $url, 0, null, 'id' );
    if ( is_wp_error( $id ) ) {
        return new WP_REST_Response( [ 'error' => 'descarga_fallida', 'detalle' => $id->get_error_message() ], 500 );
    }
    return new WP_REST_Response( [
        'url' => wp_get_attachment_url( $id ),
        'id'  => $id,
    ], 201 );
}
